CREATE TABLE member (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenant(id), store_id UUID NOT NULL REFERENCES store(id), code VARCHAR(40) NOT NULL, name VARCHAR(80) NOT NULL, phone VARCHAR(30) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version BIGINT NOT NULL DEFAULT 0, UNIQUE(store_id,code), UNIQUE(store_id,phone));
CREATE TABLE member_wallet (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenant(id), store_id UUID NOT NULL REFERENCES store(id), member_id UUID NOT NULL REFERENCES member(id), balance_cents BIGINT NOT NULL DEFAULT 0 CHECK(balance_cents>=0), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version BIGINT NOT NULL DEFAULT 0, UNIQUE(store_id,member_id));
CREATE TABLE wallet_transaction (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenant(id), store_id UUID NOT NULL REFERENCES store(id), wallet_id UUID NOT NULL REFERENCES member_wallet(id), member_id UUID NOT NULL REFERENCES member(id), transaction_type VARCHAR(30) NOT NULL CHECK(transaction_type IN ('RECHARGE','BONUS','CONSUMPTION','ADJUSTMENT')), amount_cents BIGINT NOT NULL, balance_before_cents BIGINT NOT NULL, balance_after_cents BIGINT NOT NULL CHECK(balance_after_cents>=0), source VARCHAR(30) NOT NULL, note VARCHAR(240), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX wallet_transaction_member_idx ON wallet_transaction(tenant_id,store_id,member_id,created_at DESC);
